// 8. UNIFIED DISPATCHER (Domain Taxonomies & Custom Procedural Synthesizer)
export function getDomainOrProceduralTaxonomy(surveyData: any = {}): CurriculumModule[] {
  const rawDomain = surveyData?.skillDomain || surveyData?.targetRole || '';
  const rawGoal = surveyData?.targetGoal || '';
  const rawRole = surveyData?.targetRole || '';
  const normLevel = (surveyData?.userLevel || 'intermediate').toLowerCase();

  const text = `${rawDomain} ${rawGoal} ${rawRole}`.toLowerCase();

  if (text.includes('язык') || text.includes('иностран') || text.includes('английск') || text.includes('english') || text.includes('german') || text.includes('french') || text.includes('spanish') || text.includes('полиглот')) {
    return JSON.parse(JSON.stringify(LANGUAGES_TAXONOMY));
  }

  if (text.includes('оратор') || text.includes('речь') || text.includes('выступл') || text.includes('голос') || text.includes('дикци') || text.includes('спикер') || text.includes('презентац') || text.includes('риторик')) {
    return JSON.parse(JSON.stringify(SPEAKING_TAXONOMY));
  }

  if (text.includes('дизайн') || text.includes('design') || text.includes('ui') || text.includes('ux') || text.includes('figma') || text.includes('интерфейс') || text.includes('график') || text.includes('веб-дизайн')) {
    return JSON.parse(JSON.stringify(DESIGN_TAXONOMY));
  }

  if (text.includes('бизнес') || text.includes('стартап') || text.includes('продаж') || text.includes('маркет') || text.includes('предприним') || text.includes('менедж') || text.includes('product') || text.includes('управлен') || text.includes('saas')) {
    return JSON.parse(JSON.stringify(BUSINESS_TAXONOMY));
  }

  if (text.includes('музык') || text.includes('звук') || text.includes('гитар') || text.includes('вокал') || text.includes('петь') || text.includes('фортепиан') || text.includes('гармон') || text.includes('ритм') || text.includes('слух') || text.includes('саунд')) {
    return JSON.parse(JSON.stringify(MUSIC_TAXONOMY));
  }

  if (text.includes('backend') || text.includes('разработ') || text.includes('программ') || text.includes('архитектур') || text.includes('highload') || text.includes('распределен') || text.includes('devops') || text.includes('linux') || text.includes('код') || text.includes('баз данн')) {
    return JSON.parse(JSON.stringify(TECH_TAXONOMY));
  }

  // Any custom domain on earth: procedurally synthesized 200 blocks tailored to domain and goal
  return generateProceduralTaxonomy(
    rawDomain || 'Универсальное мастерство',
    rawGoal || 'Уверенное владение практикой',
    normLevel,
    surveyData?.baggageAndBottlenecks || ''
  );
}
